from itertools import product
from random import Random
from statistics import mean
from pathlib import Path
from time import perf_counter
import json

ALPHABET='ACGT'

def radius_two_same_length(s):
    n=len(s)
    out={s}
    for i in range(n):
        for a in ALPHABET:
            if a==s[i]:
                continue
            t=s[:i]+a+s[i+1:]
            out.add(t)
            for j in range(i+1,n):
                for b in ALPHABET:
                    if b"'!=t[j]:
                        out.add(t[:j]+b+t[j+1:])
    for i in range(n):
        t=s[:i]+s[i+1:]
        for j in range(n):
            for a in ALPHABET:
                out.add(t[:j]+a+t[j:])
    return out

def construct(words, order):
    remaining=set(words)
    code=[]
    for s in order:
        if s in remaining:
            code.append(s)
            remaining.difference_update(radius_two_same_length(s))
    return code

def single_edits(s):
    yield s
    for i in range(len(s)):
        yield s[:i]+s[i+1:]
        for a in ALPHABET:
            if a!=s[i]:
                yield s[:i]+a+s[i+1:]
    for i in range(len(s)+1):
        for a in ALPHABET:
            yield s[:i]+a+s[i:]

def check_disjoint_single_edit_balls(code):
    owners={}
    for s in code:
        for t in single_edits(s):
            previous=owners.setdefault(t,s)
            if previous!=s:
                raise AssertionError((previous,s,t))
    return len(owners)

results=[]
for n in [7,8,9]:
    start=perf_counter()
    words=['"''.join(s) for s in product(ALPHABET,repeat=n)]
    code=construct(words,words)
    total=check_disjoint_single_edit_balls(code)
    Path(f'tmp/pdfs/lexicographic-code-n{n}.txt').write_text('\\n'.join(code)+'\\n')
    result={'n':n,'lexicographic_codewords':len(code),'single_edit_balls_verified_disjoint':True,'total_distinct_received_words':total,'seconds':round(perf_counter()-start,3)}
    if n==7:
        counts=[]
        for seed in range(10):
            order=words.copy()
            Random(seed).shuffle(order)
            counts.append(len(construct(words,order)))
        result['random_counts_10_seeds']=counts
        result['random_mean']=mean(counts)
    results.append(result)
    print(json.dumps(result),flush=True)
Path('tmp/pdfs/greedy-check-results.json').write_text(json.dumps(results,indent=2)+'\\n')
